from heapq import heappop, heappush


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0

    times = sorted({t for s, e, _ in jobs for t in (s, e)})
    m = len(times)
    idx = {t: i for i, t in enumerate(times)}

    adj: list[list[list[int]]] = [[] for _ in range(m)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        adj[u].append([v, cap, cost, len(adj[v])])
        adj[v].append([u, 0, -cost, len(adj[u]) - 1])

    for i in range(m - 1):
        add_edge(i, i + 1, k, 0)

    for s, e, p in jobs:
        add_edge(idx[s], idx[e], 1, -p)

    INF = 10**18
    pot = [INF] * m
    pot[0] = 0
    for u in range(m):
        pu = pot[u]
        if pu == INF:
            continue
        for v, cap, cost, _ in adj[u]:
            if cap > 0 and pu + cost < pot[v]:
                pot[v] = pu + cost

    flow = 0
    total_cost = 0

    while flow < k:
        dist = [INF] * m
        parent_v = [-1] * m
        parent_e = [-1] * m
        dist[0] = 0
        pq = [(0, 0)]

        while pq:
            d, u = heappop(pq)
            if d != dist[u]:
                continue
            pu = pot[u]
            for ei, (v, cap, cost, _) in enumerate(adj[u]):
                if cap > 0:
                    nd = d + cost + pu - pot[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        parent_v[v] = u
                        parent_e[v] = ei
                        heappush(pq, (nd, v))

        if dist[m - 1] == INF:
            break

        for i in range(m):
            if dist[i] < INF:
                pot[i] += dist[i]

        if pot[m - 1] >= 0:
            break

        add = k - flow
        v = m - 1
        while v != 0:
            u = parent_v[v]
            ei = parent_e[v]
            if adj[u][ei][1] < add:
                add = adj[u][ei][1]
            v = u

        v = m - 1
        while v != 0:
            u = parent_v[v]
            ei = parent_e[v]
            edge = adj[u][ei]
            edge[1] -= add
            adj[v][edge[3]][1] += add
            v = u

        flow += add
        total_cost += add * pot[m - 1]

    return -total_cost
